		type ipv4_addr
		flags timeout
	}
	set ids_quarantine_mac {
		type ether_addr
		flags timeout
	}

	set authenticated_ztna_users {
		type ipv4_addr . ether_addr
		flags dynamic,timeout
		timeout 28800s
	}
	set authenticated_ztna_tunnel {
		type ipv4_addr
		flags dynamic,timeout
		timeout 28800s
	}
	set authenticated_ztna_users6 {
		type ipv6_addr . ether_addr
		flags dynamic,timeout
		timeout 28800s
	}
	set authenticated_ztna_tunnel6 {
		type ipv6_addr
		flags dynamic,timeout
		timeout 28800s
	}

	set iot_isolated {
		type ether_addr
	}

	chain input {
		type filter hook input priority filter; policy drop;

		ip saddr @bruteforce_jail drop comment "bruteforce-jail"
		ip saddr @ids_quarantine drop comment "ids-quarantine"
		ip6 saddr @bruteforce_jail6 tcp dport { 22, 443 } drop comment "bruteforce-jail6"
		ether saddr @bruteforce_jail_mac tcp dport { 22, 443 } drop comment "bruteforce-jail-mac"
		meta nfproto ipv6 ether saddr @ids_quarantine_mac drop comment "ids-quarantine-ipv6"
		iifname @iot_ifaces udp sport 5353 udp dport 53530 accept comment "iot-mdns-replies"
		ether saddr @iot_isolated udp dport { 53, 67 } accept comment "iot-isolated-dhcp-dns"
		ether saddr @iot_isolated tcp dport 53 accept comment "iot-isolated-dns-tcp"
		ether saddr @iot_isolated drop comment "iot-isolated-input"
		iifname "lo" accept
		iifname { "eth0" } icmpv6 type { nd-neighbor-solicit, nd-neighbor-advert } ip6 hoplimit 255 accept comment "ipv6-nd"
		iifname { "eth0" } ip6 saddr fe80::/10 icmpv6 type nd-router-advert ip6 hoplimit 255 accept comment "ipv6-ra"
		iifname { "eth0" } ip6 saddr fe80::/10 icmpv6 type mld-listener-query ip6 hoplimit 1 accept comment "ipv6-mld"
		iifname { "eth0" } icmpv6 type { destination-unreachable, packet-too-big, time-exceeded, parameter-problem } accept comment "ipv6-errors"
		iifname { "eth0" } icmpv6 type echo-request limit rate 5/second burst 10 packets accept comment "ipv6-ping"
		iifname { "eth0" } ip6 saddr fe80::/10 udp sport 547 udp dport 546 accept comment "ipv6-dhcpv6-client"
		iifname { "eth1", "eth1.30" } icmpv6 type { nd-neighbor-solicit, nd-neighbor-advert, nd-router-solicit } ip6 hoplimit 255 accept comment "ipv6-lan-nd"
		iifname { "eth1", "eth1.30" } icmpv6 type echo-request limit rate 5/second burst 10 packets accept comment "ipv6-lan-ping"
		ct state established,related accept
		ct state invalid drop
		meta nfproto ipv6 jump ipv6_input
		iifname @lan_ifaces udp dport 53 accept comment "dns-resolver"
		iifname @lan_ifaces tcp dport 53 accept comment "dns-resolver"
		iifname @iot_ifaces tcp dport { 22, 443 } drop comment "no-management-from-iot"
		iifname @vpn_ifaces tcp dport { 22, 443 } drop comment "no-management-from-vpn"
		iifname @wan_ifaces tcp dport { 22, 443 } drop comment "no-management-from-wan"
		udp dport 51820 accept comment "wireguard"

		iifname @lan_ifaces tcp dport 22 counter accept comment "rule:ssh"

		limit rate 20/minute burst 20 packets log prefix "fr_os/drop/input: " comment "log-default-drop"
	}

	chain ipv6_input {
		iifname { "eth1" } meta l4proto { tcp, udp } th dport 53 accept comment "ipv6-dns"
		iifname { "eth0" } udp dport 51820 accept comment "ipv6-wireguard"
		iifname "wg0" icmpv6 type echo-request limit rate 5/second burst 10 packets accept comment "ipv6-vpn-ping"
		iifname "wg0" meta nfproto ipv6 reject with icmpv6 type admin-prohibited comment "ipv6-vpn-not-served"
		meta nfproto ipv6 meta pkttype != host drop comment "ipv6-not-for-the-router"
		meta nfproto ipv6 limit rate 20/minute burst 20 packets log prefix "fr_os/drop/input: " comment "log-ipv6-drop"
		meta nfproto ipv6 drop comment "ipv6-default-drop"
	}

	chain forward {
		type filter hook forward priority filter; policy drop;

		iifname "wg0" meta nfproto ipv6 ip6 daddr != fc00::/7 reject with icmpv6 type admin-prohibited comment "ipv6-vpn-ula-only"
		oifname "wg0" meta nfproto ipv6 ip6 saddr != fc00::/7 drop comment "ipv6-vpn-ula-only"
		meta nfproto ipv6 iifname != { "eth0", "eth1", "eth1.30", "wg0" } drop comment "ipv6-not-routed-here"
		meta nfproto ipv6 oifname != { "eth0", "eth1", "eth1.30", "wg0" } drop comment "ipv6-not-routed-here"
		meta nfproto ipv6 iifname { "eth1", "eth1.30" } fib saddr . iif oif missing drop comment "ipv6-lan-spoofed"
		meta nfproto ipv6 iifname { "eth0" } fib saddr oifname { "eth1", "eth1.30" } drop comment "ipv6-lan-source-from-wan"
		iifname { "eth0" } ip6 saddr fc00::/7 drop comment "ipv6-ula-from-internet"
		iifname { "eth0" } ip6 daddr fc00::/7 drop comment "ipv6-ula-from-internet"
		oifname { "eth0" } ip6 saddr fc00::/7 reject with icmpv6 type admin-prohibited comment "ipv6-ula-to-internet"
		oifname { "eth0" } ip6 daddr fc00::/7 reject with icmpv6 type admin-prohibited comment "ipv6-ula-to-internet"
		ip saddr @ids_quarantine drop comment "ids-quarantine-forward"
		meta nfproto ipv6 ether saddr @ids_quarantine_mac drop comment "ids-quarantine-ipv6"
		iifname { "eth1", "eth1.30" } udp dport 443 reject comment "sni-filter-no-quic"
		ether saddr @iot_isolated oifname @wan_ifaces accept comment "iot-isolated-internet"
		ether saddr @iot_isolated drop comment "iot-isolated-forward"
		ct state established,related accept
		ct state invalid drop
		meta nfproto ipv6 iifname { "eth0" } oifname @lan_ifaces ip6 daddr & ::ffff:ffff:ffff:ffff == ::5054:ff:fe12:3456 tcp dport 443 counter accept comment "pinhole:nas-https"
		meta nfproto ipv6 iifname { "eth0" } limit rate 20/minute burst 20 packets log prefix "fr_os/drop/forward: " comment "log-ipv6-inbound"
		meta nfproto ipv6 iifname { "eth0" } drop comment "ipv6-no-inbound"

		iifname @lan_ifaces oifname @wan_ifaces counter accept comment "rule:lan-out"
		meta day { "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday" } meta hour "00:00:00"-"00:14:59" iifname @iot_ifaces oifname @wan_ifaces counter drop comment "rule:night"
		meta day { "Monday", "Tuesday", "Wednesday", "Thursday", "Friday" } meta hour "16:15:00"-"18:14:59" iifname @iot_ifaces oifname @wan_ifaces counter drop comment "rule:night"
		meta day { "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday" } meta hour "18:15:00"-"23:59:59" iifname @iot_ifaces oifname @wan_ifaces counter drop comment "rule:night"
		meta time < 1796115600 iifname @lan_ifaces oifname @wan_ifaces tcp dport 8000-8100 counter accept comment "rule:temp"
		iifname @lan_ifaces oifname @wan_ifaces ip saddr 10.73.1.5/32 counter drop comment "rule:by-addr"
		iifname @lan_ifaces oifname @wan_ifaces ip6 saddr 2001:db8:5::/48 counter drop comment "rule:by-addr"

		limit rate 20/minute burst 20 packets log prefix "fr_os/drop/forward: " comment "log-default-drop"
	}

	chain output {
		type filter hook output priority filter; policy accept;
	}

	chain prerouting {
		type nat hook prerouting priority dstnat; policy accept;

		iifname @wan_ifaces tcp dport 8443 dnat ip to 10.73.1.10:443 comment "nat:portfwd:web"
	}

	chain postrouting {
		type nat hook postrouting priority srcnat; policy accept;

		meta nfproto ipv4 oifname @wan_ifaces masquerade comment "nat:masquerade:wan"
	}
}

